import http from 'node:http';
const estados=['revision','pendiente_pago','comprobante_recibido','pagado','cancelado'];
http.createServer((req,res)=>{res.setHeader('Content-Type','application/json');const url=new URL(req.url,'http://127.0.0.1:3127');if(url.pathname==='/health')return res.end('{}');if(url.pathname==='/rest/v1/pedidos_tilopay')return res.end(JSON.stringify({estado:'pagado',cliente:{modalidad:url.searchParams.get('id')?.endsWith('5')?'express':'retiro'},entorno:url.searchParams.get('id')?.endsWith('1')?'pruebas':'produccion'}));if(url.pathname==='/rest/v1/pedidos_manuales'){const i=Number((url.searchParams.get('id')??'').slice(-1));return res.end(JSON.stringify({cliente:{modalidad:i===5?'express':'retiro'},estado:estados[i]??'comprobante_recibido',metodo:'sinpe',total_productos:500,costo_envio:0,total_cobrar:500,articulos:[{nombre:'CONECTOR DC HEMBRA 5.5 2.1MM DC12-36V FXXDCFH1001C',cantidad:1}],comprobante_path:'fixture',correo_cliente_en:'2026-10-13T00:00:00Z'}));}return res.end('null');}).listen(Number(process.env.SG_PEDIDO_VISTA_PORT??3127),'127.0.0.1');
